import os
import torch


class Config:
    # ==========================================
    # System & Reproducibility
    # ==========================================
    SEED = 42
    DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    NUM_WORKERS = os.cpu_count()

    # ==========================================
    # Data Paths
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the provided script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(
        METADATA_DIR, "val.csv"
    )  # Note: We use K-Fold, so we might merge or just use train.csv
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Output directory for this specific idea/experiment
    WORKING_DIR = "./working/idea_8"
    OUTPUT_DIR = WORKING_DIR  # Alias

    # Ensure working directory exists
    os.makedirs(WORKING_DIR, exist_ok=True)

    # ==========================================
    # Model Architecture
    # ==========================================
    # Using ConvNeXt Small pre-trained on ImageNet-22k and fine-tuned on 1k
    # This matches the successful architecture from previous iterations
    MODEL_NAME = "convnext_small.fb_in22k_ft_in1k"

    # ==========================================
    # Hyperparameters
    # ==========================================
    IMG_SIZE = 224  # Fixed resolution
    BATCH_SIZE = 32  # Batch size fitting in A100 memory

    # Training Schedule
    WARMUP_EPOCHS = 1  # Freeze backbone, train head
    FINETUNE_EPOCHS = 30  # Unfreeze all, fine-tune
    TOTAL_EPOCHS = WARMUP_EPOCHS + FINETUNE_EPOCHS

    # Optimization
    LR = 1e-5  # Conservative learning rate for fine-tuning
    WEIGHT_DECAY = 1e-4  # Standard weight decay

    # Cross-Validation
    N_FOLDS = 5  # 5-Fold Stratified Cross-Validation

    # ==========================================
    # Label Information
    # ==========================================
    # This will be populated dynamically or hardcoded if known.
    # Since we have 120 classes, we set the count here.
    NUM_CLASSES = 120

    def __str__(self):
        """Prints the configuration."""
        attributes = [
            attr
            for attr in dir(self)
            if not attr.startswith("__") and not callable(getattr(self, attr))
        ]
        config_str = "Current Configuration:\n"
        for attr in attributes:
            config_str += f"{attr}: {getattr(self, attr)}\n"
        return config_str
